// TH18 v1.00a st05bs.ecl.txt:971-1163 (BossCard4 + BossCard4_Et/_at/_at2).
// Source t0 = target frame124: spell_begin at frame3, pattern waits 120, then BossCard4 t0.
// Entry position (0,128) from Boss common movePos and Boss4 prelude (B:469-509).
const TIME_LIMIT: int = 3722;
const SOURCE_LIMIT: int = 3600;
const SPELL_ID: int = 56;
const TH18_BIG_STAR_R: int = 720; // type23, radius 7, colors 1-6.

// BossCard4_at2: etEx type 0x200000 VELTIME a=180 r=2.0 from speed 1.0.
xformdef ACCEL_180 {
    set_accel(0.0055556fx);
    wait(180);
    set_accel(0fx);
}

// BossCard4_Et: flag303 (noninteractive, no offscreen retirement), local-coordinate task.
// moveVel(F0,2); moveVelTime(200, mode7, F1=+-1deg, 0.01) then wait(300), delete.
// BossCard4_at first runs at t1, waits 30, then etOn every rank gap until the t300 delete.
async sub child(x: fx, y: fx, a0: int, step: int, color: int, gap: int) {
    var ca: int = a0;
    var spd: fx = 2fx;
    for t in 0..300 {
        if $frame >= self_int(2) { return; }
        if t >= 1 {
            if t <= 200 {
                ca = ca + step;
                spd = spd + 0.01fx;
            }
            x = x + cos(ca as angle) * spd;
            y = y + sin(ca as angle) * spd;
        }
        if t >= 31 && (t-31) % gap == 0 {
            // Infinite L=512, judgment far=0.9L, w=16 -> target width 2*(16/4)=8.
            // startup 60, expand 20, hold 60, shrink 10; constant-width active is the
            // documented expand approximation (full width 20 frames early).
            _ = laser(color, x, y, (ca+32768) as angle, 460.8fx, 8fx, 60, 81, 10);
        }
        wait(1);
    }
}

// BossCard4: 5 children per ring, F0 one RANDRAD then +2pi/5, I0=2,4,6,8,10, F1=+-1deg.
sub ring(dir: int, gap: int) {
    var a: int = rand(65536)-32768;
    var step: int = 182;
    if dir < 0 { step = -182; }
    for i in 0..5 {
        spawn child($self_x, $self_y, a, step, 2+i*2, gap);
        a = a + 65536/5;
        if a > 32768 { a = a - 65536; }
        if a < -32768 { a = a + 65536; }
    }
}

// BossCard4_at2: etAim 2 (aimed ring), etCount GI0 x 1, speed 1, six rings rotated
// by (2pi/GI0)/6; colors 1,6,5,4,3,2. One RANDRAD per call.
sub at2(n: int) {
    var c: int = rand(65536)-32768;
    var step: int = 65536/(6*n);
    var aim: int = aim_player() as int;
    for k in 0..6 {
        var color: int = 1;
        if k == 1 { color = 6; }
        if k == 2 { color = 5; }
        if k == 3 { color = 4; }
        if k == 4 { color = 3; }
        if k == 5 { color = 2; }
        for i in 0..n {
            var ang: int = aim + c + (i*65536)/n;
            _ = fire(TH18_BIG_STAR_R, color, $self_x, $self_y, 1fx, ang as angle, ACCEL_180, none);
        }
        c = c + step;
        if c > 32768 { c = c - 65536; }
        if c < -32768 { c = c + 65536; }
    }
}

// BossCard4 moveLimit(0,144,128,64) and moveRand(60,4,1). The source speed slot keeps
// mode0 (linear decay); angle slot is constant, so the observable path is P(k)=P(k-1)+v(k).
// int slot0 = next-step count; fx0/1 = logical unit vector.
sub arm_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -64fx { nx = -64fx; }
    if nx > 64fx { nx = 64fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_step();
}
sub move_rand() {
    // Source 405b90 = signed unit random * pi. Values are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -32fx {
        a = r/3;
    } else if $self_x > 32fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad, nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_step();
    }
}

async sub pattern() {
    wait(120);
    set_self_int(2, $frame+SOURCE_LIMIT);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT); // BossCard4 movePosTime(60,4)
    wait(120);                              // source t60/t120 labels; first ring at t120
    var rank: int = global(GVAR_RANK);
    var gi0: int = 1;
    var a_max: int = 3;
    if rank == 1 { gi0 = 3; a_max = 8; }
    if rank == 2 { gi0 = 5; a_max = 10; }
    if rank == 3 { gi0 = 8; a_max = 12; }
    var gap: int = 7;
    if rank == 0 { gap = 16; }
    if rank == 1 { gap = 8; }
    loop {
        if $frame >= self_int(2) { return; }
        ring(1, gap);
        wait(200);
        if $frame >= self_int(2) { return; }
        at2(gi0);
        if gi0 < a_max { gi0 = gi0 + 1; }
        move_rand();
        card_wait(60);
        if $frame >= self_int(2) { return; }
        ring(-1, gap);
        wait(200);
        if $frame >= self_int(2) { return; }
        at2(gi0);
        if gi0 < a_max { gi0 = gi0 + 1; }
        move_rand();
        card_wait(60);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // Boss setHitbox(48,48) -> radius 24
    set_hurtbox(20fx); // Boss setHurtbox(40,40) -> radius 20
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 100000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
